css:
.nir-tote { width: 90mm; border: 2px solid #000; padding: 3mm; text-align: center; font-family: Arial, sans-serif; }
.nir-tote .nir-type { font-size: 11pt; font-weight: bold; text-transform: uppercase; }
.nir-tote img { width: 100%; height: 18mm; }
.nir-tote .nir-id { font-family: monospace; font-size: 16pt; letter-spacing: 1px; }
